CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, bio TEXT, image TEXT, CHECK (length(trim(username)) > 0), CHECK (length(trim(email)) > 0));
--;;
CREATE TABLE follows (follower_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, followed_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (follower_id, followed_id), CHECK (follower_id <> followed_id));
--;;
CREATE TABLE articles (id BIGSERIAL PRIMARY KEY, author_id BIGINT NOT NULL REFERENCES users(id), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published' CHECK (status IN ('draft','published')), published_at TIMESTAMPTZ, revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((status='draft' AND published_at IS NULL) OR (status='published' AND published_at IS NOT NULL)));
--;;
CREATE INDEX articles_published_order ON articles (created_at DESC, id DESC) WHERE status='published';
--;;
CREATE INDEX articles_author_order ON articles (author_id, created_at DESC, id DESC);
--;;
CREATE TABLE article_tags (article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, tag TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY (article_id, tag), UNIQUE (article_id, position));
--;;
CREATE INDEX article_tags_tag ON article_tags (tag, article_id);
--;;
CREATE TABLE favorites (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, PRIMARY KEY (user_id, article_id));
--;;
CREATE INDEX favorites_article ON favorites (article_id);
--;;
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY, article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, author_id BIGINT NOT NULL REFERENCES users(id), body TEXT NOT NULL CHECK (length(trim(body)) > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
--;;
CREATE INDEX comments_article ON comments (article_id, created_at, id);
--;;
CREATE TABLE exports (id UUID PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, articles JSONB);
--;;
CREATE TABLE shares (id TEXT PRIMARY KEY, article_id BIGINT NOT NULL UNIQUE REFERENCES articles(id) ON DELETE CASCADE, key_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
